def outcome(size: int, parses: bool, nodes: int, edges: int, valid: bool, cost: int, got: int, want: int) -> str:
    if not parses:
        return "REJECTED"
    if not valid:
        return "REJECTED"
    if size > 4096:
        return "OVERBUDGET"
    if nodes >= 100 or edges >= 300:
        return "OVERBUDGET"
    if cost >= 1000000:
        return "OVERBUDGET"
    return "MATCH"
